import type { Cart } from '../models/cart';

export function checkoutTotal(cart: Cart, shippingCents: number): number {
  if (cart.items.length === 0) throw new Error('Cannot check out an empty cart');
  const subtotal = cart.items.reduce((sum, item) => sum + item.unitPriceCents * item.quantity, 0);
  return subtotal + shippingCents;
}

