export class InventoryService {
  constructor(private readonly stock: Map<string, number>) {}

  reserve(productId: string, quantity: number): boolean {
    const remaining = this.stock.get(productId) ?? 0;
    if (quantity <= 0 || remaining < quantity) return false;
    this.stock.set(productId, remaining - quantity);
    return true;
  }
}

