import type { Address } from '../models/address';

export function shippingQuote(address: Address, weightGrams: number): number {
  if (weightGrams <= 0) throw new Error('A parcel must have a positive weight');
  const baseCents = address.countryCode === 'US' ? 500 : 1500;
  return baseCents + Math.ceil(weightGrams / 1000) * 125;
}

