import type { Coupon } from '../models/coupon';

export function applyCoupon(subtotalCents: number, coupon: Coupon, now: Date): number {
  if (coupon.expiresAt <= now || subtotalCents < coupon.minimumCents) return subtotalCents;
  return Math.max(0, subtotalCents - Math.round(subtotalCents * coupon.percentOff / 100));
}

