import { Injectable } from '@nestjs/common';

@Injectable()
export class TicketsService {
  private readonly tickets = new Map<string, { subject: string; closed: boolean }>();

  open(id: string, subject: string) {
    const ticket = { subject: subject.trim(), closed: false };
    this.tickets.set(id, ticket);
    return ticket;
  }

  close(id: string): boolean {
    const ticket = this.tickets.get(id);
    if (!ticket) return false;
    ticket.closed = true;
    return true;
  }
}

