import { Injectable } from '@nestjs/common';

@Injectable()
export class AssignmentService {
  chooseAgent(agents: readonly { id: string; openTickets: number; available: boolean }[]): string | null {
    const available = agents.filter(agent => agent.available);
    available.sort((left, right) => left.openTickets - right.openTickets);
    return available[0]?.id ?? null;
  }
}

