@Injectable()
export class EscalationService {
  overdue(createdAt: Date, resolvedAt: Date | null, now: Date, maximumMinutes: number): boolean {
    if (resolvedAt !== null) return false;
    return now.getTime() - createdAt.getTime() > maximumMinutes * 60_000;
  }
}

