import { useEffect } from 'react';

export function useKeyboardShortcut(key: string, run: () => void): void {
  useEffect(() => {
    const handle = (event: KeyboardEvent) => { if (event.key === key) run(); };
    window.addEventListener('keydown', handle);
    return () => window.removeEventListener('keydown', handle);
  }, [key, run]);
}

